import type { Meta, StoryObj } from '@storybook/react-vite';
import { useState, type ReactNode } from 'react';
import { IconBookmark, IconBuilding05 } from '../../icons';
import { ACCOUNT_MENU } from './headerStoryData';
import { CloudIcon, HeaderAccount, HeaderAppButton, HeaderButton, HeaderLogo, HeaderMenuItem, TasksIcon } from './HeaderParts';

const componentDescription = `
Молекулы шапки — живут только в ней. Источник — Figma UI Kit «Практис», node 986:1967.

- **HeaderMenuItem** — пункт меню: иконка 20 + текст 16; наведение — голубая полоска снизу,
  текущий раздел — синяя; точка-метка — **Bulb** кита: зелёная «есть новое», красная «нужно действие»;
  счётчик (\`count\`) — тот же Bulb, синий, после текста (как в боковом меню).
- **HeaderButton** — уведомления, задачи, «Загрузки», доп. кнопки: 49×49, с подписью — шире;
  счётчик зелёный или красный; у «Загрузок» — крутилка и ошибка.
- **HeaderAppButton** — единственная круглая кнопка, привлекает внимание, открывает спецмодалку.
- **HeaderAccount** — кабинет: аватар, имя, организация; открывает меню (DropdownMenu кита).
  Узкий вариант (планшет) — только аватар.
- **HeaderLogo** — Praktis, Praktis RU, Setl Group, Айкона; в тёмной теме сама берёт тёмную версию из макета.
`;

const meta = {
  title: 'UI Kit/Header/Части',
  parameters: { layout: 'padded', docs: { description: { component: componentDescription }, story: { height: '400px' } } },
  // Меню кабинета — выпадающий список: в Docs без запаса высоты он обрезается (гайд 2)
  decorators: [(Story) => <div style={{ minHeight: 340 }}><Story /></div>],
  tags: ['autodocs'],
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

const Row = ({ children, label }: { children: ReactNode; label: string }) => (
  <div style={{ display: 'grid', gridTemplateColumns: '160px 1fr', alignItems: 'center', gap: 16, fontFamily: 'Inter, sans-serif' }}>
    <span style={{ fontSize: 12, color: '#7e7e7e' }}>{label}</span>
    <div style={{ display: 'flex', gap: 24, alignItems: 'center', flexWrap: 'wrap' }}>{children}</div>
  </div>
);

export const MenuItems: Story = {
  name: 'HeaderMenuItem',
  parameters: { docs: { description: { story: 'Клик — пункт становится текущим. Наведение — голубая полоска.' } } },
  render: () => <MenuDemo />,
};

function MenuDemo() {
  const [active, setActive] = useState('objects');
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      <Row label="клик — текущий">
        <HeaderMenuItem icon={<IconBuilding05 />} label="Объекты" active={active === 'objects'} onClick={() => setActive('objects')} />
        <HeaderMenuItem icon={<IconBookmark />} label="Задачи" active={active === 'tasks'} onClick={() => setActive('tasks')} />
        <HeaderMenuItem label="Без иконки" active={active === 'plain'} onClick={() => setActive('plain')} />
      </Row>
      <Row label="точки-метки">
        <HeaderMenuItem icon={<IconBuilding05 />} label="Есть новое" dot="green" active={active === 'new'} onClick={() => setActive('new')} />
        <HeaderMenuItem icon={<IconBookmark />} label="Нужно действие" dot="red" active={active === 'todo'} onClick={() => setActive('todo')} />
      </Row>
      <Row label="счётчик">
        <HeaderMenuItem icon={<IconBuilding05 />} label="Заявки" count={3} active={active === 'req'} onClick={() => setActive('req')} />
        <HeaderMenuItem icon={<IconBookmark />} label="Тендеры" count="99+" active={active === 'tenders'} onClick={() => setActive('tenders')} />
      </Row>
    </div>
  );
}

export const Buttons: Story = {
  name: 'HeaderButton',
  parameters: { docs: { description: { story: 'Пустая, со счётчиком «есть новое» (зелёный) и «важное» (красный); с подписью и без; «Загрузки» — идёт загрузка и ошибка. Под кнопками — какая нажата.' } } },
  render: () => <ButtonsDemo />,
};

function ButtonsDemo() {
  const [last, setLast] = useState<string | null>(null);
  const click = (s: string) => () => setLast(s);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <Row label="без подписи">
        <HeaderButton label="Уведомления" onClick={click('пустая')} />
        <HeaderButton label="Уведомления" count="99+" onClick={click('счётчик зелёный')} />
        <HeaderButton label="Уведомления" count="99+" countColor="red" onClick={click('счётчик красный')} />
      </Row>
      <Row label="с подписью">
        <HeaderButton label="Уведомления" showLabel onClick={click('пустая с подписью')} />
        <HeaderButton label="Уведомления" showLabel count="99+" onClick={click('зелёный с подписью')} />
        <HeaderButton label="Уведомления" showLabel count="99+" countColor="red" onClick={click('красный с подписью')} />
      </Row>
      <Row label="задачи">
        <HeaderButton label="Задачи" icon={<TasksIcon />} onClick={click('задачи')} />
        <HeaderButton label="Задачи" icon={<TasksIcon />} count="3" onClick={click('задачи со счётчиком')} />
        <HeaderButton label="Задачи" showLabel icon={<TasksIcon />} count="3" onClick={click('задачи с подписью')} />
      </Row>
      <Row label="«Загрузки»">
        <HeaderButton label="Загрузки" icon={<CloudIcon />} status="loading" onClick={click('загрузка без подписи')} />
        <HeaderButton label="Загрузки" showLabel icon={<CloudIcon />} status="loading" onClick={click('загрузка')} />
        <HeaderButton label="Загрузки" showLabel icon={<CloudIcon />} status="error" onClick={click('ошибка загрузки')} />
      </Row>
      <span style={{ fontSize: 12, color: '#7e7e7e', fontFamily: 'Inter, sans-serif', minHeight: 15 }}>{last ? `Нажато: ${last}` : ' '}</span>
    </div>
  );
}

export const AppButton: Story = {
  name: 'HeaderAppButton',
  parameters: { docs: { description: { story: 'Наведение и нажатие — голубой темнее. Неактивная — серая.' } } },
  render: () => (
    <Row label="обычная / неактивная">
      <HeaderAppButton label="Все сервисы" />
      <HeaderAppButton label="Все сервисы" disabled />
    </Row>
  ),
};

export const Account: Story = {
  name: 'HeaderAccount',
  parameters: { docs: { description: { story: 'Клик — меню кабинета. Длинное имя обрезается отточием. Узкий вариант — только аватар.' } } },
  render: () => <AccountDemo />,
};

function AccountDemo() {
  const [last, setLast] = useState<string | null>(null);
  return (
